   502  static gboolean
   503  fu_coswid_firmware_parse(FuFirmware *firmware,
   504                           GInputStream *stream,
   505                           gsize offset,
   506                           FwupdInstallFlags flags,
   507                           GError **error)
   508  {
   509  #ifdef HAVE_CBOR
   510          FuCoswidFirmware *self = FU_COSWID_FIRMWARE(firmware);
   511          FuCoswidFirmwarePrivate *priv = GET_PRIVATE(self);
   512          struct cbor_load_result result = {0x0};
   513          struct cbor_pair *pairs = NULL;
   514          g_autoptr(cbor_item_t) item = NULL;
   515          g_autoptr(GBytes) fw = NULL;
   516
   517          fw = fu_input_stream_read_bytes(stream, offset, G_MAXSIZE, error);
   518          if (fw == NULL)
   519                  return FALSE;
   520          item = cbor_load(g_bytes_get_data(fw, NULL), g_bytes_get_size(fw), &result);
   521          if (item == NULL) {
   522                  g_set_error(error,
   523                              FWUPD_ERROR,
   524                              FWUPD_ERROR_NOT_SUPPORTED,
   525                              "failed to parse CBOR at offset 0x%x: 0x%x",
   526                              (guint)result.error.position,
   527                              result.error.code);
   528                  return FALSE;
   529          }
   530          fu_firmware_set_size(firmware, result.read);
   531
   532          /* pretty-print the result */
   533          if (g_getenv("FWUPD_CBOR_VERBOSE") != NULL) {
   534                  cbor_describe(item, stdout);
   535                  fflush(stdout);
   536          }
   537
   538          /* sanity check */
   539          if (!cbor_isa_map(item)) {
   540                  g_set_error_literal(error,
   541                                      FWUPD_ERROR,
   542                                      FWUPD_ERROR_INVALID_DATA,
   543                                      "root item is not a map");
   544                  return FALSE;
   545          }
   546
   547          /* parse out anything interesting */
   548          pairs = cbor_map_handle(item);
   549          for (gsize i = 0; i < cbor_map_size(item); i++) {
   550                  FuCoswidTag tag_id = 0;
   551                  if (!fu_coswid_read_tag(pairs[i].key, &tag_id, error))
   552                          return FALSE;
   553
   554                  /* identity can be specified as a string or in binary */
   555                  if (tag_id == FU_COSWID_TAG_TAG_ID) {
   556                          g_autofree gchar *str = NULL;
   557                          if (cbor_isa_string(pairs[i].value)) {
   558                                  str = fu_coswid_read_string(pairs[i].value, error);
   559                                  if (str == NULL) {
   560                                          g_prefix_error(error, "failed to parse tag-id: ");
   561                                          return FALSE;
   562                                  }
   563                          } else if (cbor_isa_bytestring(pairs[i].value) &&
   564                                     cbor_bytestring_length(pairs[i].value) == 16) {
   565                                  str = fwupd_guid_to_string(
   566                                      (const fwupd_guid_t *)cbor_bytestring_handle(pairs[i].value),
   567                                      FWUPD_GUID_FLAG_NONE);
   568                          }
   569                          if (str != NULL)
   570                                  fu_firmware_set_id(firmware, str);
   571                  } else if (tag_id == FU_COSWID_TAG_SOFTWARE_NAME) {
   572                          g_free(priv->product);
   573                          priv->product = fu_coswid_read_string(pairs[i].value, error);
   574                          if (priv->product == NULL) {
   575                                  g_prefix_error(error, "failed to parse product: ");
   576                                  return FALSE;
   577                          }
   578                  } else if (tag_id == FU_COSWID_TAG_SOFTWARE_VERSION) {
   579                          g_autofree gchar *str = fu_coswid_read_string(pairs[i].value, error);
   580                          if (str == NULL) {
   581                                  g_prefix_error(error, "failed to parse software-version: ");
   582                                  return FALSE;
   583                          }
   584                          fu_firmware_set_version(firmware, str);
   585                  } else if (tag_id == FU_COSWID_TAG_VERSION_SCHEME) {
   586                          if (!fu_coswid_read_version_scheme(pairs[i].value,
   587                                                             &priv->version_scheme,
   588                                                             error))
   589                                  return FALSE;
   590                  } else if (tag_id == FU_COSWID_TAG_SOFTWARE_META) {
   591                          if (!fu_coswid_parse_one_or_many(pairs[i].value,
   592                                                           fu_coswid_firmware_parse_meta,
   593                                                           self, /* user_data */
   594                                                           error))
   595                                  return FALSE;
   596                  } else if (tag_id == FU_COSWID_TAG_LINK) {
   597                          if (!fu_coswid_parse_one_or_many(pairs[i].value,
   598                                                           fu_coswid_firmware_parse_link,
   599                                                           self, /* user_data */
   600                                                           error))
   601                                  return FALSE;
   602                  } else if (tag_id == FU_COSWID_TAG_PAYLOAD) {
   603                          if (!fu_coswid_parse_one_or_many(pairs[i].value,
   604                                                           fu_coswid_firmware_parse_payload,
   605                                                           self, /* user_data */
   606                                                           error))
   607                                  return FALSE;
   608                  } else if (tag_id == FU_COSWID_TAG_ENTITY) {
   609                          if (!fu_coswid_parse_one_or_many(pairs[i].value,
   610                                                           fu_coswid_firmware_parse_entity,
   611                                                           self, /* user_data */
   612                                                           error))
   613                                  return FALSE;
   614                  } else {
   615                          g_debug("unhandled tag %s from root", fu_coswid_tag_to_string(tag_id));
   616                  }
   617          }
   618
   619          /* device not supported */
   620          if (fu_firmware_get_id(firmware) == NULL && fu_firmware_get_version(firmware) == NULL &&
   620          if (fu_firmware_get_id(firmware) == NULL && fu_firmware_get_version(firmware) == NULL &&
   621              priv->product == NULL && priv->entities->len == 0 && priv->links->len == 0) {
   622                  g_set_error_literal(error,
   623                                      FWUPD_ERROR,
   624                                      FWUPD_ERROR_NOT_SUPPORTED,
   625                                      "not enough SBoM data");
   626                  return FALSE;
   627          }
   628
   629          /* success */
   630          return TRUE;
   631  #else
   632          g_set_error_literal(error,
   633                              FWUPD_ERROR,
   634                              FWUPD_ERROR_NOT_SUPPORTED,
   635                              "not compiled with CBOR support");
   636          return FALSE;
   637  #endif
   638  }
