   736          gsize bufsz = 0;
   737          g_autofree guchar *buf = NULL;
   738          g_autoptr(cbor_item_t) root = cbor_new_indefinite_map();
   739          g_autoptr(cbor_item_t) item_meta = cbor_new_indefinite_map();
   740
   741          /* preallocate the map structure */
   742          fu_coswid_write_tag_string(root, FU_COSWID_TAG_LANG, "en-US");
   743          if (fu_firmware_get_id(firmware) != NULL) {
   744                  fwupd_guid_t uuid = {0};
   745                  if (fwupd_guid_from_string(fu_firmware_get_id(firmware),
   746                                             &uuid,
   747                                             FWUPD_GUID_FLAG_NONE,
   748                                             NULL)) {
   749                          fu_coswid_write_tag_bytestring(root,
   750                                                         FU_COSWID_TAG_TAG_ID,
   751                                                         (const guint8 *)&uuid,
   752                                                         sizeof(uuid));
   753                  } else {
   754                          fu_coswid_write_tag_string(root,
   755                                                     FU_COSWID_TAG_TAG_ID,
   756                                                     fu_firmware_get_id(firmware));
   757                  }
   758          }
   759          fu_coswid_write_tag_bool(root, FU_COSWID_TAG_CORPUS, TRUE);
   760          if (priv->product != NULL)
   761                  fu_coswid_write_tag_string(root, FU_COSWID_TAG_SOFTWARE_NAME, priv->product);
   762          if (fu_firmware_get_version(firmware) != NULL) {
   763                  fu_coswid_write_tag_string(root,
   764                                             FU_COSWID_TAG_SOFTWARE_VERSION,
   765                                             fu_firmware_get_version(firmware));
   766          }
   767          if (priv->version_scheme != FU_COSWID_VERSION_SCHEME_UNKNOWN)
   768                  fu_coswid_write_tag_u16(root, FU_COSWID_TAG_VERSION_SCHEME, priv->version_scheme);
   769          fu_coswid_write_tag_item(root, FU_COSWID_TAG_SOFTWARE_META, item_meta);
   770          fu_coswid_write_tag_string(item_meta, FU_COSWID_TAG_GENERATOR, PACKAGE_NAME);
   771          if (priv->summary != NULL)
   772                  fu_coswid_write_tag_string(item_meta, FU_COSWID_TAG_SUMMARY, priv->summary);
   773          if (priv->colloquial_version != NULL) {
   774                  fu_coswid_write_tag_string(item_meta,
   775                                             FU_COSWID_TAG_COLLOQUIAL_VERSION,
   776                                             priv->colloquial_version);
   777          }
   778
   779          /* add entities */
   780          if (priv->entities->len > 0) {
   781                  g_autoptr(cbor_item_t) item_entities = cbor_new_indefinite_array();
   782                  for (guint i = 0; i < priv->entities->len; i++) {
   783                          FuCoswidFirmwareEntity *entity = g_ptr_array_index(priv->entities, i);
   784                          g_autoptr(cbor_item_t) item_entity = cbor_new_indefinite_map();
   785                          g_autoptr(cbor_item_t) item_roles = cbor_new_indefinite_array();
   786                          if (entity->name != NULL) {
   787                                  fu_coswid_write_tag_string(item_entity,
   788                                                             FU_COSWID_TAG_ENTITY_NAME,
   789                                                             entity->name);
   790                          }
   791                          if (entity->regid != NULL) {
   792                                  fu_coswid_write_tag_string(item_entity,
   793                                                             FU_COSWID_TAG_REG_ID,
   794                                                             entity->regid);
   795                          }
   796                          for (guint j = 0; entity->roles[j] != FU_COSWID_ENTITY_ROLE_UNKNOWN; j++) {
   797                                  g_autoptr(cbor_item_t) item_role =
   798                                      cbor_build_uint8(entity->roles[j]);
   799                                  if (!cbor_array_push(item_roles, item_role))
   800                                          g_critical("failed to push to indefinite array");
   801                          }
   802                          fu_coswid_write_tag_item(item_entity, FU_COSWID_TAG_ROLE, item_roles);
   803                          if (!cbor_array_push(item_entities, item_entity))
   804                                  g_critical("failed to push to indefinite array");
   805                  }
   806                  fu_coswid_write_tag_item(root, FU_COSWID_TAG_ENTITY, item_entities);
   807          }
   808
   809          /* add links */
   810          if (priv->links->len > 0) {
   811                  g_autoptr(cbor_item_t) item_links = cbor_new_indefinite_array();
   812                  for (guint i = 0; i < priv->links->len; i++) {
   813                          FuCoswidFirmwareLink *link = g_ptr_array_index(priv->links, i);
   814                          g_autoptr(cbor_item_t) item_link = cbor_new_indefinite_map();
   815                          if (link->href != NULL) {
   816                                  fu_coswid_write_tag_string(item_link,
   817                                                             FU_COSWID_TAG_HREF,
   818                                                             link->href);
   819                          }
   820                          fu_coswid_write_tag_s8(item_link, FU_COSWID_TAG_REL, link->rel);
   821                          if (!cbor_array_push(item_links, item_link))
   822                                  g_critical("failed to push to indefinite array");
   823                  }
   824                  fu_coswid_write_tag_item(root, FU_COSWID_TAG_LINK, item_links);
   825          }
   826
   827          /* add payloads */
   828          if (priv->payloads->len > 0) {
   829                  g_autoptr(cbor_item_t) item_payloads = cbor_new_indefinite_array();
   830                  for (guint i = 0; i < priv->payloads->len; i++) {
   831                          FuCoswidFirmwarePayload *payload = g_ptr_array_index(priv->payloads, i);
   832                          fu_coswid_firmware_write_payload(item_payloads, payload);
   833                  }
   834                  fu_coswid_write_tag_item(root, FU_COSWID_TAG_PAYLOAD, item_payloads);
   835          }
   836
   837          /* serialize */
   838          buflen = cbor_serialize_alloc(root, &buf, &bufsz);
   839          if (buflen > bufsz) {
   840                  g_set_error_literal(error,
   841                                      FWUPD_ERROR,
   842                                      FWUPD_ERROR_NOT_SUPPORTED,
   843                                      "CBOR allocation failure");
   844                  return NULL;
   845          }
   846          return g_byte_array_new_take(g_steal_pointer(&buf), buflen);
   847  #else
   848          g_set_error_literal(error,
   849                              FWUPD_ERROR,
   850                              FWUPD_ERROR_NOT_SUPPORTED,
   851                              "not compiled with CBOR support");
   852          return NULL;
   853  #endif
   854  }
